-- ============================================================
-- FULL-TEXT SEARCH (Phase 10) — Unsupported() type, never
-- managed by Prisma itself; adapted from
-- prisma/migrations/20260821000000_add_resource_search_vector
--
-- Using a trigger instead of GENERATED ALWAYS AS: PostgreSQL's
-- immutability check for generated columns rejects to_tsvector()
-- (and any wrapper around it) regardless of how it's declared. A
-- BEFORE INSERT/UPDATE trigger computes the exact same value with no
-- such restriction, since trigger bodies are not subject to the
-- generated-column immutability check.
-- ============================================================

ALTER TABLE "Resource" ADD COLUMN "searchVector" tsvector;

CREATE OR REPLACE FUNCTION resource_search_vector_trigger() RETURNS trigger AS $$
BEGIN
  NEW."searchVector" :=
    setweight(to_tsvector('french', coalesce(NEW."title", '')), 'A') ||
    setweight(to_tsvector('french', coalesce(array_to_string(NEW."keywords", ' '), '')), 'B') ||
    setweight(to_tsvector('french', coalesce(NEW."abstract", '')), 'C') ||
    setweight(to_tsvector('french', coalesce(NEW."description", '')), 'D');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER resource_search_vector_update
  BEFORE INSERT OR UPDATE ON "Resource"
  FOR EACH ROW EXECUTE FUNCTION resource_search_vector_trigger();

CREATE INDEX "Resource_searchVector_idx" ON "Resource" USING GIN ("searchVector");

COMMIT;
